window.VO = [{"id":"c01","text":"You there, keep a hand on your wallet. There's a pickpocket at the east gate.","at":0.16,"t0":0.08,"t1":4.185},{"id":"c02","text":"Did you hear? There's a pickpocket at the east gate, everyone's saying it!","at":9.47,"t0":4.735,"t1":8.815},{"id":"c03","text":"East gate, saab. Pickpocket. Police are going there now.","at":18.93,"t0":9.465,"t1":12.81},{"id":"n01","text":"So where's the pickpocket?","at":27.22,"t0":13.61,"t1":15.055},{"id":"n02","text":"He's at the west gate, where he took a wallet in the very first second.","at":32.71,"t0":16.355,"t1":20.1},{"id":"n03","text":"And the warning was his.","at":41.2,"t0":20.6,"t1":21.91},{"id":"n04b","text":"So the three people who warned you were one man, three times.","at":45.62,"t0":22.81,"t1":25.995},{"id":"n05c","text":"They sounded like three witnesses, and not one of them had seen him,","at":53.59,"t0":26.795,"t1":30.32},{"id":"n05d","text":"but he'd seen every hand go to a pocket, yours too.","at":61.14,"t0":30.57,"t1":33.405},{"id":"n07","text":"So while the police ran east and grabbed the first man they saw running,","at":68.61,"t0":34.305,"t1":38.045},{"id":"n08b","text":"he walked back through every pocket he'd watched them touch.","at":76.33,"t0":38.165,"t1":41.005},{"id":"c04","text":"You there, keep a hand on your wallet.","at":86.61,"t0":43.305,"t1":45.195}];
